"""Render completed R63 receipts; never predict or combine independent gains."""
from pathlib import Path
import json,sys
s=json.loads(Path(sys.argv[1]).read_text());out=Path(sys.argv[2]);p=s['primary'];before=p['medians']['before'];after=p['medians']['after'];comparison=p['comparisons']['after_over_before'];families=s['allocation_families']
lines=['# R63: current frame-shape guards','',f"Candidate build: `{s['static']['after']['source']}`. Baseline R62 build: `{s['static']['before']['source']}`. Accepted baseline checkpoint: `{s['baseline_provenance']['accepted_checkpoint']}`.",'',f"The complete eight-byte level-12 call measured **{after['multiple_of_reference']:.6f}× the reference**, from **{before['multiple_of_reference']:.6f}×** in this matched baseline cohort. Candidate/baseline elapsed: **{comparison['pooled_ratio']:.8f}×** ({s['changes_percent']['primary_seconds']:+.4f}%). The freshly measured reference median was {p['reference_seconds']*1000:.6f} ms.",'','The two frame-admission paths reuse their prepared current-shape predicate after current typed fields have been checked. The predicate additionally requires a complete-axis proof: nested parameter relations or output-size checks that its direct axes cannot establish retain ordinary constructor validation. This separates footprint-recipe eligibility from shape-proof eligibility while preserving the fallback and its error order. The nested-output-overflow counterexample and actual caller/constructor recovery are retained as regressions.','', 'Engine, Compute, Stdlib, Runtime and GPU were rebuilt coherently with their retained flags/features and warnings-as-errors. Core, math, syntax and external artifacts remain frozen. The candidate emits its Object, descriptor and metadata afresh; all three must match the R62 baseline byte-for-byte. No compressor source, algorithm, source allocation site or timing boundary changes.','', '| Metric | Reference | R62 baseline | R63 candidate | Change |','|---|---:|---:|---:|---:|',f"| Primary elapsed (ms) | {p['reference_seconds']*1000:.6f} | {before['seconds']*1000:.6f} | {after['seconds']*1000:.6f} | {s['changes_percent']['primary_seconds']:+.4f}% |"]
for section,key,label in [('cpu','instructions','Retired instructions'),('cpu','cycles','CPU cycles'),('allocation','allocation_requests','Allocation requests'),('allocation','requested_bytes','Requested bytes'),('allocation','reallocations','Reallocations'),('allocation','peak_live_usable','Peak allocator live usable bytes'),('allocation','incremental_peak_live_usable','Incremental allocator peak'),('cpu','rss_after','RSS after call'),('cpu','physical_after','Physical footprint after call')]:
 values=[s[section][variant][key]['median'] for variant in ['reference','before','after']];change=s['changes_percent'][key]
 lines.append('| '+label+' | '+' | '.join(f'{v:,.1f}' if int(v)!=v else f'{v:,.0f}' for v in values)+' | '+('—' if change is None else f'{change:+.4f}%')+' |')
lines+=['','Primary elapsed, CPU counters, heap counters and CPU-time samples are separate serial cohorts. Their percentages are not multiplied or combined. Requested bytes represent allocation requests, not initialized bytes copied. Allocator peak and post-call OS footprint are different measures; the latter is not peak RSS and includes retained compiler/catalog/image storage.','', '## Allocation mechanism','', '| Family | Baseline requests / bytes | Candidate requests / bytes | Request / byte delta |','|---|---:|---:|---:|']
for key in ['flat_frame_shape_validation','composed_frame_admission','combined_candidate','separate_resolved_extent_solver','outside_candidate']:
 b=families['before']['families'][key];a=families['after']['families'][key];d=families['family_deltas'][key]
 lines.append(f"| {key} | {b['requests']:,} / {b['requested_bytes']:,} | {a['requests']:,} / {a['requested_bytes']:,} | {d['requests']:+,} / {d['requested_bytes']:+,} |")
lines+=['', 'The pre-change ceiling was 68 requests / 1,024 requested bytes, predicting 8,105 requests / 98,227,372 bytes only if all attributed requests disappeared. The table reports actual complete-census results. Combined-candidate is the union of the first two rows; do not add it to them. The extent solver and outside-candidate totals are separate, disjoint families.', '', families['source_attribution_caveat'],'', 'Before-family attribution uses the retained R62 complete census, pinned by SHA-256 `ae2452719ce2d535ab0528d207d1cf9109da2d5b9b96f0ae3bbe449f5e3a1cee`. It is historical trace evidence; its totals reconcile with the fresh R63 before heap cohort. The after census is freshly collected for R63 and reconciles with fresh after heap counters. Both timing, hardware-counter and sample variants are also freshly measured. Raw symbols, per-size counts and generated-entry return groups remain in `allocation-families.json`. Matching heap totals do not manufacture a fresh baseline stack trace, and no per-branch or nonallocating-visit count is claimed.','', '## Matched pairs and adverse observations','', '| Pair | Baseline ms | Candidate ms | Candidate/baseline |','|---|---:|---:|---:|']
for group in p['groups']:lines.append(f"| {group['group']} | {group['medians']['before']*1000:.6f} | {group['medians']['after']*1000:.6f} | {group['after_over_before']:.8f}× |")
lines+=['',f"{comparison['improving_groups']}/4 independently prepared pairs and {comparison['improving_blocks']}/64 alternating blocks improved. Four pairs ×16 blocks ×31 calls ×2 variants produce 3,968 timed observations. Blocks within one pair are descriptive, not independent repetitions."]
adverse=s['contrary_primary_groups']
lines.append('Adverse or unchanged primary pairs: '+(', '.join(str(x['group'])+f" ({100*(x['after_over_before']-1):+.4f}%)" for x in adverse) if adverse else 'none.'))
d=s['diagnostic_cpu_elapsed'];lines+=['',f"The separate CPU-counter cohort elapsed was {d['before']['median_seconds']*1000:.6f} → {d['after']['median_seconds']*1000:.6f} ms ({d['change_percent']:+.6f}%). These 32 observations per variant are excluded from primary elapsed and retain their independent direction.",'','Other observed median increases:','','```json',json.dumps(s['contrary_counter_directions'],indent=2),'```','', '## Binary and baseline provenance','', '| Metric | R62 baseline | R63 candidate |','|---|---:|---:|']
for key,label in [('code_bytes','Generated text bytes'),('stack_bytes','Machine entry stack bytes'),('typed_ir_version','Typed IR version'),('abi_version','ABI version')]:lines.append(f"| {label} | {s['static']['before'][key]:,} | {s['static']['after'][key]:,} |")
lines+=['','Object/image/metadata equality: '+str(all(s['artifact_pin_equality'].values()))+'. The unchanged generated bytes have unchanged static instruction content. Hardware retired instructions can still change because this patch changes host admission work. `binary-audit.json` records each actual image pin.', '', s['baseline_provenance']['source_note'],'',s['baseline_provenance']['binary_note'],'', 'These historical notes preserve provenance; no R62 measurement or test execution is counted as an R63 observation.','', '## Workload and correctness','', 'Input: eight bytes `abcdefgh`. Exact raw output: `[75,76,74,78,73,77,75,207,0,0]`, independently inflated. Output capacity 13 is cleared/reused. The tree has 262,144 U16 entries; the cache has 1,500,513 U32 words; depth is 300 and nice length 258. Original source allocation sites, input aliases and allocator are retained. Logical work is 60,260,219,686 and comparison work is 47,612; neither is a hardware instruction count. Successful invocations finish with zero managed bytes/nodes.','', '```json',json.dumps(s['source_pins'],indent=2),'```','', '## Qualification','',f"Status: **{s['validation']['status']}**. Counts below are actual executed receipts; inventory-only rows are omitted from this view and remain in `validation.json`. Batches overlap.",'', '| Receipt | Expected tests | Observed | Exit / expected | Passed |','|---|---:|---:|---:|---|']
for row in s['validation']['checks']:
 if row.get('inventory_only'):continue
 lines.append(f"| `{row['receipt']}` | {row.get('expected_tests','—')} | {row.get('observed_tests',row.get('cases','—'))} | {row.get('exit','—')} / {row.get('expected_exit',0)} | {row['passed']} |")
lines+=['',s['validation']['expected_negative_control_scope'],'',s['validation']['runtime_coverage']['scope'],'','Six Engine `frame_shape::tests::` tests are explicitly scheduled in CI with `full_compiler,native-artifact,sequence_buffers`. The local `ci.py` Engine batch actually executes them using the retained broader Engine test feature configuration, which includes those required flags among its other enabled cfg features. This is not a claim that the local build used exactly the minimal CI feature set or that remote CI completed; the complete actual command is archived.','', 'Earlier failed attempts and dispositions:']
for row in s['validation']['prior_failures']:lines.append('- `'+row['receipt']+'` — '+row.get('classification','unclassified')+': '+row['disposition'])
if not s['validation']['prior_failures']:lines.append('None recorded.')
lines+=['','Skipped coverage:']
for row in s['validation']['skipped_coverage']:lines.append('- '+row.get('test',row.get('coverage'))+': '+row['disposition'])
lines+=['','Decision: **'+s['decision']['status']+'**. '+s['decision']['reason'],'','## Replay','','Run `python3 reconstruct.py /new/empty/output/path` from the published packet. Replay verifies every archived file version and reproduces scorecard JSON/CSV, allocation-family JSON, profile JSON and validation JSON without compilation, compressor execution or external scratch inputs.','', 'This complete small-input result does not establish larger-input throughput or a standalone minimum-memory footprint. Each reported direction and decision comes from R63 receipts; no earlier-round gains are multiplied into this result.','']
out.write_text('\n'.join(lines))
